(98, 'Тревел-портмоне на магнітах', 25, 1, 18, '2019-08-29 18:12:45', '2025-07-30 16:06:19', NULL, 'Тревел-портмоне на магнітах з натуральної шкіри - Lavoks', NULL, 'Величезний вибір моделей, кольору. Відправлення виробів в день замовлення. На виготовлення індивідуального замовлення 1-2 дні. Відправляємо післяплатою або по передоплаті. Іменне тиснення. Гарантія від виробника.', 'trevel-portmone-na-magnitah', 'Тревел-портмоне на магнітах', '<p><span style="color: #7f8187; font-family: Montserrat, sans-serif;">Тревел-портмоне на магнітах,&nbsp; розмір 21х12 см в складеному стані. Чотири містких відділення під картки, окреме відділення для паспорта, та два містких відділення, куди можна покласти паперові гроші, білети та за потребою ще пару паспортів. Зачиняється на потужні неодімови магніти.</span></p>', '', 'categories/August2019/IIJ27il696A8KOBVU0KQ.JPG', 'trevel-portmone-na-magnitah-cropped.webp', '', '', 'trevel-portmone-na-magnitah', 0.7, 'weekly', '', '', NULL, NULL, NULL, NULL, NULL, NULL),
(100, 'Гаманці "Фрог"', 25, 1, 12, '2019-09-26 03:47:00', '2025-07-30 16:06:22', NULL, 'Гаманець "Фрог" з натуральної шкіри - Lavoks', NULL, 'Величезний вибір моделей і кольору. Завжди в наявності. Відправлення виробів в день замовлення. На виготовлення індивідуального замовлення 1-2 дні. ', 'gamanec-frog', 'Гаманець "Фрог"', '<p><iframe src="https://www.youtube.com/embed/rawdlk178AQ?t=1s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/FGttUHTSVx8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe></p>\n<p><span style="font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;">Маленький гаманець, який </span><span lang="RU" style="font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;">увійде</span><span style="font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;"> в будь-як</span><span lang="RU" style="font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;">у</span><span style="font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;"> кишеню чи сумочку. Такий собі шкіряний мішечок з застібкою зверху. Застібка відкривається при натисканні на кінцівки пальцями, та різко закривається коли відпускаєте, з характерним звуком, звідти і назва. &nbsp;Застібка &ndash; це дві металеві полоски, які пружинять при натисканні.</span><span style="text-indent: -18pt; font-size: 12pt; line-height: 107%; font-family: Symbol;"><span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: ''Times New Roman'';">&nbsp;&nbsp;</span></span><span style="text-indent: -18pt; font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;">Розмір:</span> <span style="text-indent: -18pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif; color: black;">10 * 10 см</span></p>\n<p class="MsoListParagraph" style="text-indent: -18.0pt; mso-list: l0 level1 lfo1;">&nbsp;</p>\n<p class="MsoListParagraph" style="text-indent: -18.0pt; mso-list: l0 level1 lfo1;"><!-- [if !supportLists]--><span style="font-size: 12.0pt; line-height: 107%; font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">&middot;<span style="font: 7.0pt ''Times New Roman'';">&nbsp; &nbsp; &nbsp; &nbsp;</span></span></span></p>', '', 'categories/July2022/41jDRZss25AMPV7KXhTQ.JPG', 'gamanci-frog-cropped.webp', '', '', 'gamanci-frog', 0.7, 'weekly', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(101, 'Сумки чоловічі "Балу"', 23, 1, 13, '2019-10-26 16:32:49', '2025-11-14 17:50:28', NULL, 'Сумка чоловіча "Балу" з натуральної шкіри - Lavoks', NULL, 'Величезний вибір моделей сумок і кольору. Завжди в наявності. Відправлення виробів в день замовлення. На виготовлення сумки індивідуального замовлення 1-2 дні.', 'sumka-cholovicha-balu', 'Сумка чоловіча "Балу"', '<p class="MsoNormal"><span style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white;"><iframe src="https://www.youtube.com/embed/citnBUN9ZUo" width="310" height="174" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Сумка чоловіча "Балу" має невеликий розмір 20*20*6 см. Попереду об</span><span lang="RU" style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white; mso-ansi-language: RU;">`</span><span style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white;">ємна кишеня на замочку. Позаду кишеня теж на замочку, всередині 2 кишені &ndash; один звичайний, другий на замочку. </span></p>', '', 'categories/October2019/FlnrKHij1Q2QNxX5dMoA.JPG', 'sumki-cholovichi-balu-cropped.webp', '', '', 'sumki-cholovichi-balu', 0.7, 'weekly', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(102, 'Ключниці "Фрог", розмір S', 28, 1, 23, '2019-10-31 19:57:21', '2025-10-01 20:46:30', NULL, 'Ключниця "Фрог", розмір S з натуральної шкіри - Lavoks', NULL, 'Широкий асортимент аксесуарів з натуральної шкіри - брелоки, ключниці, килимки для мишки, косметички, холдери для навушників. Відправлення день в день, більше 60 видів і кольорів шкір', 'klyuchnicya-frog-rozmir-s', 'Ключниця "Фрог", розмір S', '<p class="MsoNormal"><span style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white;"><iframe src="https://www.youtube.com/embed/l1PM9Zgb2VM" width="313" height="176" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/WK9TLcym0CQ" width="310" height="174" allowfullscreen="allowfullscreen"></iframe> <iframe src="https://www.youtube.com/embed/FGttUHTSVx8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Маленька ключниця, яка </span><span lang="RU" style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white; mso-ansi-language: RU;">не займатиме багато місця </span><span style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white;">в будь-як</span><span lang="RU" style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white; mso-ansi-language: RU;">ій</span><span style="font-family: Montserrat; mso-bidi-font-family: Arial; background: white;"> кишені чи сумочці. Такий собі шкіряний мішечок з застібкою зверху. Застібка відкривається при натисканні на кінцівки пальцями, та різко закривається коли відпускаєте, з характерним звуком, звідти і назва.<span style="mso-spacerun: yes;">&nbsp; </span>Застібка &ndash; це дві металеві полоски, які пружинять при натисканні. </span><span style="font-family: Montserrat; mso-bidi-font-family: Arial;">Всередині шкіряний шнурок з кільцем для ключів <span style="background: white;"><span style="mso-spacerun: yes;">&nbsp;</span>Дуже цікава штучка, навіть просто погратись )</span></span><span style="text-indent: -18pt; font-family: Symbol;"><span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: ''Times New Roman'';">&nbsp; </span></span><span style="text-indent: -18pt; font-family: Montserrat;">Розмір:</span> <span style="text-indent: -18pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-family: Montserrat;">10 * 10 см.</span></p>\n<p class="MsoListParagraph" style="text-indent: -18.0pt; mso-list: l0 level1 lfo1;">&nbsp;</p>\n<p class="MsoListParagraph" style="text-indent: -18.0pt; mso-list: l0 level1 lfo1;"><!-- [if !supportLists]--><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">&middot;<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></span></p>', '', 'categories/October2019/Zx0hB9fBl2NpRt57Tcla.JPG', 'klyuchnici-frog-rozmir-s-cropped.webp', '', '', 'klyuchnici-frog-rozmir-s', 0.7, 'weekly', '', '', NULL, NULL, 0, NULL, NULL, NULL),
