(126, 'Ремені шириною 30 мм , ремінна шкіра', 40, 1, 3, '2020-08-31 03:35:48', '2025-07-30 16:07:42', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/ASNlA8aRUcg?t=97s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/u7wD1vvmdqI?t=26s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe></p>', '', 'categories/June2023/G6YkIBNWeaGPjI8oZqw0.JPG', 'remeni-shirinoyu-30-mm-reminna-shkira-cropped.webp', '', '', 'remeni-shirinoyu-30-mm-reminna-shkira', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(127, 'Ремені шириною 20 мм, ремінна шкіра', 40, 1, 4, '2020-09-04 06:48:47', '2025-07-30 16:07:44', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/ASNlA8aRUcg" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/u7wD1vvmdqI?t=31s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe></p>', '', 'categories/September2020/IKLSpu0yL4mVdDnIaZiU.JPG', 'remeni-shirinoyu-20-mm-reminna-shkira-cropped.webp', '', '', 'remeni-shirinoyu-20-mm-reminna-shkira', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(128, 'Косметичкі "Монро"', 28, 1, 6, '2020-09-04 13:31:03', '2025-10-01 20:46:29', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/FGttUHTSVx8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Косметичка Монро &ndash; багатофункціональний виріб. Має одне велике відділення та застібку на блискавку. Можна використовувати для косметики, як аптечку, або як тревел-портмоне (паспорт, гроші та інші документи). Також туди можна покласти окуляри або телефон.</p>', '', 'categories/March2023/kANASczJXs3CMDlolQmQ.JPG', 'kosmetichki-monro-cropped.webp', '', '', 'kosmetichki-monro', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(129, 'Ремені шириною 40 мм', 40, 1, 5, '2020-09-24 02:40:25', '2025-07-30 16:08:49', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/ASNlA8aRUcg?t=4s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/u7wD1vvmdqI?t=32s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe></p>', '', 'categories/September2020/I0If2pBrYiz39cjjfiw2.JPG', 'remeni-shirinoyu-40-mm-cropped.webp', '', '', 'remeni-shirinoyu-40-mm', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(130, 'Ремені шириною 35 мм', 40, 1, 6, '2020-09-24 02:43:19', '2025-07-30 16:08:50', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/ASNlA8aRUcg?t=4s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/u7wD1vvmdqI?t=32s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe></p>', '', 'categories/June2023/JGWENWFicZZAx9psCXhd.JPG', 'remeni-shirinoyu-35-mm-cropped.webp', '', '', 'remeni-shirinoyu-35-mm', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(131, 'Рюкзаки "Мадрид Плюс"', 26, 1, 4, '2020-11-05 20:34:34', '2025-07-30 16:08:52', NULL, '', NULL, '', NULL, NULL, '<p>Рюкзак Мадрид ,&nbsp; розмір 36*26*11 см, всередині шкіряна перегородка з кишенею</p>', '', 'categories/November2020/EsSoON9MbQPYWAZVdeVi.JPG', 'ryukzaki-madrid-plyus-cropped.webp', '', '', 'ryukzaki-madrid-plyus', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(132, 'Ремені шириною 20 мм', 40, 1, 7, '2020-11-17 04:09:23', '2025-07-30 16:08:54', NULL, '', NULL, '', NULL, NULL, '', '', 'categories/November2020/8a6i7hdhbxYlOlYiaNtM.JPG', 'remeni-shirinoyu-20-mm-cropped.webp', '', '', 'remeni-shirinoyu-20-mm', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(133, 'Гаманці "Альф"', 25, 0, 19, '2020-11-26 02:21:36', '2025-07-30 16:08:59', NULL, '', NULL, '', NULL, NULL, '<p>Гаманець, який вас здивує. Має 2 відділення для купюр, чотири кишені для id-карток. Закривається гаманець на магніт. Позаду гаманця є так звана &laquo;європейська&raquo; монетниця -дуже вмістка та зручна у використанні річ. Коли ви відкриваєте цю монетницю, вона стає маленькою чотирикутною коробочкою, в якій видно всі монетки. Гаманець має дуже маленьки розміри, але при цьому в нього можна багато чого покласти.</p>', '', 'categories/November2020/XokCHQBnm6dhm1p3leXR.JPG', 'gamanci-al-f-cropped.webp', '', '', 'gamanci-al-f', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(134, 'Зажими для горошей "Гібрид з монетницею"', 27, 1, 7, '2020-11-30 21:20:07', '2025-07-30 16:09:01', NULL, '', NULL, '', NULL, NULL, '<p>Зажим для грошей " Гібрид" Незвичайний зажим для грошей з 4 кишенями під картки, застібається на кнопку. Розмір 10 * 10 см. Позаду гаманця є так звана &laquo;європейська&raquo; монетниця -дуже вмістка та зручна у використанні річ. Коли ви відкриваєте цю монетницю, вона стає маленькою чотирикутною коробочкою, в якій видно всі монетки. У відмінності від інших подібних моделей, сюди влазять всі види купюр євро.</p>', '', 'categories/November2020/f0HMEUeFjyzaGyBeMR3x.JPG', 'zazhimi-dlya-goroshej-gibrid-z-monetniceyu-cropped.webp', '', '', 'zazhimi-dlya-goroshej-gibrid-z-monetniceyu', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(135, 'Ремені шириною 30 мм', 40, 1, 8, '2020-12-01 04:40:39', '2025-07-30 16:09:02', NULL, '', NULL, '', NULL, NULL, '', '', 'categories/June2023/c1XkPUh42rbJiBcVGojx.JPG', 'remeni-shirinoyu-30-mm-cropped.webp', '', '', 'remeni-shirinoyu-30-mm', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(136, 'Накладка на взуття для стендової стрільби', 28, 1, 30, '2021-05-25 13:31:49', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '<p>Накладка на взуття призначена для зручного упору стволів рушниці. Використовується для стендової стрільби, полювання, спортингу для запобігання подряпин і потертостей на взутті. Кріпиться за допомогою кнопки, протягується через шнурки.</p>', '', 'categories/May2021/gas0WWqWcCYv4J6ltIp1.JPG', 'nakladka-na-vzuttya-dlya-stendovoyi-stril-bi-cropped.webp', '', '', 'nakladka-na-vzuttya-dlya-stendovoyi-stril-bi', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(137, 'Сумки "Сімба"', 23, 1, 20, '2021-05-31 02:47:29', '2025-11-14 17:50:28', NULL, '', NULL, '', NULL, NULL, '<p>&nbsp;<iframe src="https://www.youtube.com/embed/Wp7CoqgX2Z8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Сумка жіноча "Сімба" це дуже популярна, класична модель сумки, яка незалежно від моди, подобається багатьом. Розмір 24х18х8 см. Має застібку на молнію. Має кишеню позаду на замочку. &nbsp;Всередині дві кишені: одна на замочку і одна звичайна. Вся повністю з натуральної шкіри, кишені всередині теж шкіряні. Може бути виконана в 60 видах та кольорах шкір.&nbsp;</p>', '', 'categories/May2024/7DX3Ljec8DdUsXqQCnQW.JPG', 'sumki-simba-cropped.webp', '', '', 'sumki-simba', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(138, 'Ручки зі шкіри для меблів та сумок', 114, 1, 7, '2021-06-04 18:15:43', '2025-07-30 16:09:11', NULL, '', NULL, '', NULL, NULL, '<p>Ручки виготовляються переважно з ремінної шкіри товщиною 3,5 - 4 мм., з прострочкою по периметру або без. Також можемо зробити на замовлення з будь-якої галантерейної шкіри в два шари. Довжина ручки 21 см, всі розміри є на фото, доданого на сторінку товару.</p>', '', 'categories/June2021/J0m60Kow96TwY4LIftje.JPG', 'ruchki-zi-shkiri-dlya-mebliv-ta-sumok-cropped.webp', '', '', 'ruchki-zi-shkiri-dlya-mebliv-ta-sumok', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(139, 'Кліпси для сумок o bag', 114, 1, 8, '2021-06-09 02:37:49', '2025-07-30 16:09:13', NULL, '', NULL, '', NULL, NULL, '<p>Кліпси з натуральної шкіри підходять для таких моделей OBAG як: Pocket, Swing, Moon, Moonlight, Shoulder, MicroPocket і інших сумок зі змінними кліпсами. Використовуються для прикріплення ременя або ланцюга з карабіном до сумочки. Завжди в наявності близько 100 видів і кольорів шкір, з яких можуть бути виготовлені кліпси для сумок. Ширина кліпси 20 мм, інші розміри на фото, прикріпленого до фото на сторінці продукту.</p>', '', 'categories/June2021/tRBRRPffWE2PnN6r6wRh.JPG', 'klipsi-dlya-sumok-o-bag-cropped.webp', '', '', 'klipsi-dlya-sumok-o-bag', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(140, 'Сумки "Фріда"', 23, 1, 22, '2021-06-09 04:02:16', '2025-11-14 17:50:12', NULL, '', NULL, '', NULL, NULL, '<p>Сумка жіноча "Фріда" це маленька сумочка, яка багато чого може в себе вмістити) Розмір 20х14х8 см. Закривається на молнію. Має з`ємний пасок на карабінах. Має маленьку ручку. Має кишеню позаду на замочку. &nbsp;Всередині дві кишені.&nbsp; Вона повністю з натуральної шкіри, кишені всередині теж шкіряні. Може бути виконана в 60 видах та кольорах шкіри.</p>', '', 'categories/June2021/0bmXNiXlelAhDktQRSD0.JPG', 'sumki-frida-cropped.webp', '', '', 'sumki-frida', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(141, 'Картхолдери з захистом RFID "Бонд"', 30, 1, 7, '2021-07-22 01:38:35', '2025-10-19 17:50:45', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/jHRIW2b-xhY?t=8s" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Якщо ви хочете убезпечити свої банківські карти від зчитування або свій ID-паспорт від копіювання, то Вам просто необхідний цей картхолдер "Бонд" з надійним RFID-захистом. Як працює RFID-захист? Якщо помістити Ваші банківські карти з NFC-модулем або ID-паспорт всередину спеціального металевого корпусу, то все радіосигнали будуть блокуватися, тим самим запобігаючи доступ до вмісту через канали RFID / NFC. В металевий картходер можна вставити від 1 до 6 карток, навіть одна картка не випадає та гарно тримається. Шкіряна обкладинка теж має гаманець для карток (десь до 5 шт. можна також покласти)</p>', '', 'categories/July2021/N6rvwgkvAdzG6KCCC9X6.JPG', 'kartholderi-z-zahistom-rfid-bond-cropped.webp', '', '', 'kartholderi-z-zahistom-rfid-bond', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(143, 'Сумки "Йоко"', 23, 1, 23, '2021-08-18 20:36:17', '2025-11-20 20:19:56', NULL, 'Купити міні сумку Йоко з натуральної шкіри | Lavoks', NULL, 'Ультракомпактна шкіряна сумка Йоко для мінімалістів: 19x11x6 см, handmade з 150 видів шкіри (кайзер, алькор, крейзі хорс). Ідеальна для essentials, легка 250 г. Купити універсальну жіночу сумку з натуральної шкіри в Lavoks — стиль і якість!', NULL, NULL, '<h1>Сумка Йоко: Компактна елегантність для мінімалістів</h1><p>У світі, де стиль визначає впевненість, а практичність — ключ до комфорту, сумка Йоко вирізняється своєю ультракомпактною формою. Ця мініатюрна шкіряна сумочка — ідеальний вибір для тих, хто носить тільки найнеобхідніше: смартфон, ключі, картки чи помаду. Створена для динамічних жінок, що цінують лаконізм і якість, Йоко стане незамінним аксесуаром у міському ритмі — від ранкових прогулянок до вечірніх зустрічей. З нею ви відчуєте легкість і витонченість, де кожна деталь підкреслює вашу індивідуальність, перетворюючи повсякденність на стильне мистецтво.</p><h2>Дизайн, що втілює чистоту ліній</h2><p>Сумка Йоко — це есенція мінімалізму: компактна прямокутна форма з м''якими вигинами натуральної шкіри, двома зручними ручками та регульованим ремінцем для плеча. Чисті лінії, акуратні шви та відсутність зайвих елементів роблять її універсальною для будь-якого образу — від casual з джинсами до елегантного total look. Цей дизайн пасує до сучасних трендів, де простота перемагає надмірність, і легко вписується в гардероб, додаючи статусу без ваги. Купити міні сумку Йоко — обрати вічний фаворит, що не виходить з моди.</p><h2>Якість натуральної шкіри з характером</h2><p>Серце Йоко — преміальна натуральна шкіра, відібрана для довговічності та унікальності. Ми пропонуємо понад 150 видів: шкіра кайзер — стійка поверхня з легким глянцем, глянцеву алькор з глибоким насиченим кольором для затишку, матову крейзі хорс з вінтажною поверхнею чи екзотичне <a href="https://lavoks.com/tisnennya">тиснення</a> під крокодила для шику. Кожен тип зберігає природну текстуру та дихання, роблячи сумку витвором мистецтва. Виготовлена вручну майстрами з багаторічним досвідом, Йоко проходить ретельний контроль — від шаблонів до шиття. Міцні ручки не деформуються, а внутрішня кишеня з тієї ж натуральної шкіри забезпечує організованість. Ця handmade жіноча сумка витримує щоденне використання, зберігаючи форму роками — вибір для усвідомленого споживання.</p><h2>Функціональність у ультраміні форматі</h2><p>З розмірами 19 см у висоту, 11 см у ширину та 6 см у глибину, сумка Йоко — це втілення максимальної компактності для самого необхідного. Вона вміщить лише essentials: телефон, гаманець, ключі чи косметику, не обтяжуючи силует. Головний відсік з блискавкою захищає вміст, а внутрішня кишеня з натуральної шкіри додає зручності. Регульований ремінець (від 60 до 120 см) дозволяє носити хендбегом чи кросбоді — ідеально для прогулянок чи подорожей. Легка вагою близько 250 г, ця натуральна шкіряна сумка не тисне на плече, але додає впевненості. Якщо шукаєте міні сумку з шкіри для динамічного життя, Йоко — ваш must-have.</p><h2>Універсальність для будь-якого настрою</h2><p>Йоко адаптується до гардеробу завдяки розмаїттю кольорів і типів шкіри. Оберіть класичний чорний чи коричневий для офісу, яскравий смарагдовий для літа або матову крейзі хорс з вінтажною поверхнею. Це дозволяє створювати колекцію: одну для буднів, іншу для подій. Така гнучкість робить модель топ-вибором для fashion-ентузіастів, що експериментують з відтінками та рельєфами. Універсальна шкіряна сумка Йоко розширює стилістичні можливості без зайвого.</p><h2>Сумка, що відображає вашу суть</h2><p>Аксесуари розповідають історії, і Йоко — не виняток. З натуральної шкіри вона набуває унікальних слідів від ваших пригод: потертостей від ключів чи блиску від сонця. Супроводжуватиме в натхненні — на каву з друзями, бізнес-зустрічах чи романтичних вечерах, додаючи впевненості. Ця handmade сумка відображає мінімалістичну, але глибоку особистість, еволюціонуючи з вами як талісман стилю.</p><h2>Розмаїття стилів: від casual до елегантного</h2><p>Уявіть Йоко в образах: з блузкою та брюками для софістики, oversize-светром і шортами для кежуал, маленькою сукнею для вечора чи легінсами для спортивного шику. Нейтральна шкіра додає текстури, <a href="https://lavoks.com/tisnennya">тиснення</a> крокодила — драматичності. Від скандинавського мінімалізму до французького шику, вона пасує до трендів. Купити сумку міні з шкіри — розширити гардероб просто й стильно.</p><h2>Догляд за сумкою: прості правила</h2><ul><li><strong>Захист:</strong> Наносьте спрей від вологи та бруду перед виходом.</li><li><strong>Чистка:</strong> Протирайте м''якою щіткою чи вологою мікрофіброю, без агресивних засобів.</li><li><strong>Зберігання:</strong> Тримайте в пилозахисному мішку, в прохолодному місці без сонця. Для <a href="https://lavoks.com/tisnennya">тиснення</a> — гумова щітка.</li></ul><p>Ці кроки збережуть красу інвестиції.</p><h2>Інвестуйте в компактний шик</h2><p>Йоко — усвідомлений вибір якості, стилю та екологічності. З натуральної шкіри, handmade-виготовленням і універсальністю, вона окупається одразу. У час мас-маркету обирайте вічне: ця модель стане частиною життя, як улюблений ритуал. Клієнтки повертаються за новими варіантами, бо справжня мода — в деталях.</p><p>Створіть свій ідеал зараз! Натисніть "Додати в кошик" — доставка по Україні, гарантія та персональний підбір. Йоко чекає додати магії вашому стилю!</p>', '', 'categories/August2021/77hSoErW7HH8wCGC0Qot.JPG', 'sumki-joko-cropped.webp', 'Сумка Йоко: компактна елегантність з натуральної шкіри для мінімалістів', 'шкіряна сумка Йоко, міні сумка з шкіри, натуральна шкіра сумка, handmade жіноча сумка, купити сумку міні, універсальна шкіряна сумка, сумка кайзер, сумка алькор, сумка крейзі хорс, сумка тиснення крокодила, догляд за шкіряною сумкою, компактна сумка 19x11x6', 'sumki-joko', NULL, 'daily', 'Сумка Йоко: міні handmade з натуральної шкіри, 19x11x6 см', 'Компактна сумка Йоко з преміальної шкіри (кайзер з глянцем, алькор насичений колір, крейзі хорс вінтажна). Вміщує телефон, ключі, косметику. Регульований ремінець, блискавка. Купити міні сумку з шкіри для динамічного стилю в Lavoks — довговічна та елегантна!', NULL, NULL, 0, NULL, NULL, NULL),
(144, 'Сумки "Ларго Гранде"', 23, 0, 40, '2021-09-13 00:49:16', '2025-07-30 16:10:10', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/abaDkyCHgb4" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Сумка жіноча "Ларго Гранде". Це сумка доволі великого розміру 33*43*10см. Всередині кишеня для ноутбука діагональю до 17 дюймів та 2 кишені на замочку для ваших дрібничок</p>', '', 'categories/September2021/yZxjiiUlJxhSSN4imZkz.JPG', 'sumki-largo-grande-cropped.webp', '', '', 'sumki-largo-grande', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(145, 'Ремінці для килимка', 28, 1, 33, '2021-09-13 02:06:34', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '<p>Ремінець для килимка робимо по розмірах і в кольрах замовника</p>', '', 'categories/September2021/PwcKs8av8JCqoI5zyELh.JPG', 'reminci-dlya-kilimka-cropped.webp', '', '', 'reminci-dlya-kilimka', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(146, 'Ремені шириною 35 мм, ремнінна шкіра, пряжка автомат', 40, 1, 9, '2021-09-13 04:08:23', '2025-07-30 16:10:11', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/b8E9ZgMQsMQ" width="313" height="176" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/XtNwZQ4UzeU" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Принциповою відмінністю від інших ременів є конструкція пряжки-автомат. Завдяки механізму що тріщить, відбувається плавне регулювання по довжині ремня. У звичайних ремнях отвори знаходяться на відстані 25 мм. Ще одна перевага - завжди можна вкоротити ремінь, на маючи практично жодного спеціального інструменту - потрібен тільки гострий ніж або ножниці. Пряжка кріпиться до паскової смуги завдяки міцній зубчастій клямці. Особливо це важливо, коли Ви робите подарунок і не знаєте якої довжини Вам потрібен ремінь, а з усіх виробів шкіргалантереї самий безпомилковий і універсальний подарунок на наш погляд і за нашою статистикою це як раз ремінь. Ремені з ремнінної шкіри, товщина 3,5 - 4 мм, ширина 3,5 см, довжина до 150 см, пряжка на вибір. В окремих випадках ремінь можна зробити довшим.</p>', '', 'categories/September2021/USuh3JPsrO5zaDLIXX9c.JPG', 'remeni-shirinoyu-35-mm-remninna-shkira-pryazhka-avtomat-cropped.webp', '', '', 'remeni-shirinoyu-35-mm-remninna-shkira-pryazhka-avtomat', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(147, 'Гаманці "Шаде"', 25, 1, 3, '2021-09-21 15:05:29', '2025-10-29 14:10:48', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/Br5rFWczXb4" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Гаманець "Шаде", 6 відділень під картки, в кожне з яких входить по 2-3 картки, два просторих відділення, в які увійде багато грошових купюр будь-якого формату і смартфон будь-якого розміру. Одне відділення меншого розміру для паперових купюр, і ще одне відділення на блискавці (YKK), в якому можна розміщувати монетки або ще щось). Розмір 19,5х8,5х2,5 см.</p>', '', 'categories/October2025/5kdo8uVgY6Xu8apEOeKB.jpg', 'gamanci-shade-cropped.webp', '', '', 'gamanci-shade', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(148, 'Чоловічі сумки "Гудіні"', 23, 1, 14, '2021-10-04 02:58:49', '2025-11-14 17:50:28', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/MCQRXXU0sm0" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Сумка чоловіча "Гудіні" це дуже популярна, класична модель сумки, яка незалежно від моди, подобається багатьом. Розмір 24х18х8 см. Має застібку на молнію. Має кишеню позаду на замочку. &nbsp;Всередині дві кишені: одна на замочку і одна звичайна, на кнопці. Вся повністю з натуральної шкіри, кишені всередині теж шкіряні. Основні кольори - чорний, темно-коричневий, темно-синій та коньячний.</p>', '', 'categories/October2021/qScmUeTVv4Mg4jXN79c0.JPG', 'cholovichi-sumki-gudini-cropped.webp', '', '', 'cholovichi-sumki-gudini', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(149, 'Брелок з тисненням', 28, 1, 20, '2021-10-13 03:54:34', '2025-10-01 20:46:30', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/mZ7hCumP2ng" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Брелки можемо виготовити будь-якого кольору, з будь-якого типу шкіри (в рамках нашого асортименту). Асортимент наших шкір можна побачити на прикладі гаманців "Смарт". Також можемо індивідуалізувати брелок - зробити <a href="https://lavoks.com/tisnennya">тиснення</a> з Вашими ініціалами або лого вашої компанії. Розміри - 6,5 х 2,2 см.&nbsp;</p>', '', 'categories/October2021/mjC09tQrcN8ov33QGbxM.JPG', 'brelok-z-tisnennyam-cropped.webp', '', '', 'brelok-z-tisnennyam', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(150, 'Символи для тиснення які є в наявності', 88, 1, 3, '2021-10-27 01:38:24', '2025-07-30 16:10:37', NULL, '', NULL, '', NULL, NULL, '<p>Символи , які є на фото в цьому розділі нашого сайту, доступні для <a href="https://lavoks.com/tisnennya">тиснення</a> на любому нашому виробі. Набір символів буде постійно оновлюватися.</p>', '', 'categories/October2021/a5Wjw8ED0fRxcslSwt7E.JPG', 'simvoli-dlya-tisnennya-yaki-ye-v-nayavnosti-cropped.webp', '', '', 'simvoli-dlya-tisnennya-yaki-ye-v-nayavnosti', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(151, 'Підставки під склянку, костер, бірдекель', 28, 0, 31, '2021-11-03 04:47:30', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '', '', 'categories/November2021/DT3qr18jJGRSHDKzOHGQ.JPG', 'pidstavki-pid-sklyanku-koster-birdekel-cropped.webp', '', '', 'pidstavki-pid-sklyanku-koster-birdekel', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(152, 'Ключниці "Шість карабінів", розмір М', 28, 1, 11, '2021-11-04 15:45:21', '2025-10-01 20:46:29', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/BcsgvI2GuOM" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Невід''ємним супутником сучасної людини стає <strong>ключниця</strong>. Аксесуар допоможе зберігати в одному місці цілу в''язку ключів, і надійно захищає від пошкоджень інші речі в <a href="../../../sumki">сумці</a>.</p>\n<h2>Переваги ключниць Лавокс</h2>\n<p>Популярність <strong>ключниць</strong> у чоловіків і жінок не випадкова. Цей аксесуар має досить переваг:</p>\n<ol>\n<li>Ключі в ключниці не дзвенить при ходьбі.</li>\n<li>Зв''язка ключів рідше втрачається.</li>\n<li>Простіше знайти ключі в <a href="../../../sumki">сумці</a>.</li>\n<li>Гострі краї ключів не псують інші речі, які знаходяться в <a href="../../../sumki">сумці</a>.</li>\n<li>Будь-яка <em>кишенькова ключниця</em> - це відмінний спосіб завжди тримати всі ключі під рукою.</li>\n</ol>\n<p>Мода на <strong>ключниці</strong> не змінюється, завжди цінуються якісні <strong>шкіряні вироби</strong> строгого дизайну. Саме такі варіанти пропонує в <strong>Києві</strong> <a href="../../../">виробник Лавокс</a>. Ми відправляємо продукцію по всій <strong>Україні</strong>, тому від Львова до Харкова можна зустріти щасливих володарів наших аксесуарів.</p>\n<p>Ключниця " Шість карабінів" Розмір 15 х 6 см в закритому виді, розрахована на ключі довжиною до 11,5 см, 6 карабінів для ключів, фурнітура антік та нікель, виконується в любому кольорі та типу шкіри, що є в наявності (зазвичай біля 100 видів)</p>', '', 'categories/November2021/EcBSRTuq02NXkSLdrQly.JPG', 'klyuchnici-shist-karabiniv-rozmir-m-cropped.webp', '', '', 'klyuchnici-shist-karabiniv-rozmir-m', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(153, 'Підставки, костер, бірдекель зі шкіри під склянку, бокал, або інше.', 28, 1, 17, '2021-11-04 23:25:39', '2025-10-01 20:46:29', NULL, '', NULL, '', NULL, NULL, '<p>Підставка зі шкіри під склянку, бокал або інше ще має назви костер та бірдекель. Служитиме не тільки для захисту поверхні вашого столу від гарячого та мокрого, а також є стильною прикрасою та оригінальним подарунком. Виріб може бути з вашим малюнком або логотипом ( для цього зробимо індивідуальне металеве кліше), або з готовими нашими символами та малюнками. Також можемо виконати напис латинськими літерами. Усі малюнки та написи робляться методом "гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>". Розміри та форми підставки (костера, бірдекеля) можуть бути різними. Гама кольорів величезна - у нас понад 200 видів шкір.&nbsp;</p>', '', 'categories/November2021/pOGGBSvAtr6wzV0Hw5EV.JPG', 'pidstavki-koster-birdekel-zi-shkiri-pid-sklyanku-bokal-abo-inshe-cropped.webp', '', '', 'pidstavki-koster-birdekel-zi-shkiri-pid-sklyanku-bokal-abo-inshe', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(154, 'Сумки на підкладці', 23, 1, 42, '2021-11-10 18:56:04', '2025-07-30 16:10:43', NULL, '', NULL, '', NULL, NULL, '', '', 'categories/November2021/H6TLaieDXakC61ACfR1W.JPG', 'sumki-na-pidkladci-cropped.webp', '', '', 'sumki-na-pidkladci', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(155, 'Рюкзаки на підкладці', 26, 1, 8, '2021-11-10 18:57:36', '2025-07-30 16:10:44', NULL, '', NULL, '', NULL, NULL, '', '', 'categories/November2021/jbCmg1VKjJ97E2aLye7C.JPG', 'ryukzaki-na-pidkladci-cropped.webp', '', '', 'ryukzaki-na-pidkladci', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(156, 'Ключниці "Фрог" для автомобільного ключа', 28, 1, 1, '2021-11-23 03:48:28', '2025-10-01 20:46:29', NULL, '', NULL, '', NULL, NULL, '<div class="se-component se-video-container __se__float-none"><figure style="height: 56.25%; padding-bottom: 56.25%; width: 313px;"><iframe frameborder="0" allowfullscreen="" src="https://www.youtube.com/embed/qqBLV3hPZMg" data-proportion="true" data-size="313px,56.25%" data-align="none" data-file-name="qqBLV3hPZMg" data-file-size="0" data-origin="313px,56.25%" style="width: 313px;"></iframe></figure></div><p>Маленька ключниця для автомобільного ключа, яка не займатиме багато місця&nbsp;в будь-якій кишені чи сумочці. Особливо зручно користуватися якщо у вас система безключового доступу до автомобіля й запуску двигуна. Такий собі шкіряний мішечок з застібкою зверху. Застібка відкривається при натисканні на кінцівки пальцями, та різко закривається коли відпускаєте, з характерним звуком, звідти і назва.&nbsp;&nbsp;Застібка – це дві металеві полоски, які пружинять при натисканні. Всередині шкіряний шнурок з кільцем для ключа. Розмір місця під ключ 8,5 см х 7 см. Загальний розмір 11 см х 7,5 см.</p>', '', 'categories/November2021/ZeUzawflSG8fh64DBD8G.JPG', 'klyuchnici-frog-dlya-avtomobil-nogo-klyucha-cropped.webp', '', '', 'klyuchnici-frog-dlya-avtomobil-nogo-klyucha', NULL, 'daily', '', '', NULL, NULL, 0, NULL, 0, NULL),
(157, 'Приклади готових бирок зі шкіри', 123, 1, 1, '2021-11-24 03:20:08', '2026-05-15 18:45:35', NULL, 'Шкіряні бирки, ярлики та лейбли з логотипом на замовлення | Lavoks', NULL, 'Замовляйте виготовлення шкіряних бирок, ярликів та етикеток з натуральної шкіри за ціною від 300 грн за кліше. Понад 120 кольорів, 50 стандартних розмірів. Доставка по Україні!', NULL, NULL, '<p>&nbsp;</p><h2>Виготовлення шкіряних бирок, ярликів та лейблів з логотипом</h2><p>Бажаєте підкреслити преміальність вашого бренду та зробити продукцію впізнаваною? Наша майстерня пропонує професійне виготовлення маркувальних елементів із натуральних матеріалів. Ми створюємо <strong>ярлики з натуральної шкіри</strong>, фірмові <strong>етикетки зі шкіри</strong> та зносостійкі <strong>шкіряні нашивки (лейбли)</strong> для дизайнерського одягу, головних уборів, взуття, сумок і домашнього текстилю.</p><p>Завдяки використанню методу гарячого тиснення, кожна <strong>брендована шкіряна бірка</strong> отримує чіткий, глибокий та довговічний відбиток вашого логотипу. Ми пропонуємо гнучкі умови співпраці як для невеликих крафтових майстерень, так і для великих швейних виробництв.</p><p><strong>Чому варто замовити маркувальну продукцію в Lavoks:</strong></p><p>▪️ <strong>Великий асортимент:</strong> понад 120 відтінків та різноманітні фактури натуральної шкіри під будь-який стиль.▪️ <strong>Стандартизація та кастомізація:</strong> у наявності 50 готових варіантів розмірів, а також можливість розробки унікальної форми.▪️ <strong>Допомога з кліше:</strong> повністю координуємо процес виготовлення металевого штампа (вартість від 300 грн залежно від габаритів).</p><h2>Наші <strong>шкіряні етикетки та бирки</strong> не втрачають презентабельного вигляду під час активного використання виробу, залишаючись стильним акцентом вашого бренду. Ви можете купити <strong>брендовані ярлики з натуральної шкіри</strong> в Києві або оформити замовлення з доставкою в будь-який куточок України. Створіть неповторний стиль разом із нами!</h2>', '', 'categories/November2021/bqwW3mixiZZpRDs439WE.JPG', 'prikladi-gotovih-birok-zi-shkiri-cropped.webp', 'Виготовлення шкіряних бирок та ярликів із логотипом', 'Бажаєте підкреслити преміальність вашого бренду та зробити продукцію впізнаваною? Наша майстерня пропонує професійне виготовлення маркувальних елементів із натуральних матеріалів. Ми створюємо ярлики з натуральної шкіри, фірмові етикетки зі шкіри та зносостійкі шкіряні нашивки (лейбли) для дизайнерського одягу, головних уборів, взуття, сумок і домашнього текстилю.\n\nЗавдяки використанню методу гарячого тиснення, кожна брендована шкіряна бірка отримує чіткий, глибокий та довговічний відбиток вашого логотипу. Ми пропонуємо гнучкі умови співпраці як для невеликих крафтових майстерень, так і для великих швейних виробництв.\n\nЧому варто замовити маркувальну продукцію в Lavoks:\n▪️ Великий асортимент: понад 120 відтінків та різноманітні фактури натуральної шкіри під будь-який стиль.\n▪️ Стандартизація та кастомізація: у наявності 50 готових варіантів розмірів, а також можливість розробки унікальної форми.\n▪️ Допомога з кліше: повністю координуємо процес виготовлення металевого штампа (вартість від 300 грн залежно від габаритів).\n\nНаші шкіряні етикетки та бирки не втрачають презентабельного вигляду під час активного використання виробу, залишаючись стильним акцентом вашого бренду. Ви можете купити брендовані ярлики з натуральної шкіри в Києві або оформити замовлення з доставкою в будь-який куточок України. Створіть неповторний стиль разом із нами!', 'prikladi-gotovih-birok-zi-shkiri', NULL, 'daily', 'Купити шкіряну бирку {name} з тисненням логотипу — Lavoks', 'Шкіряні бирки та лейбли на замовлення. Якісна натуральна шкіра, гаряче тиснення вашого бренду. Обирайте фірмові ярлики для одягу та сумок від майстерні Lavoks.', NULL, NULL, 0, NULL, NULL, NULL),
(158, 'Бирки прямокутні', 123, 1, 2, '2021-11-24 04:24:00', '2025-07-30 16:10:46', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/November2021/NHVOmchhve2eaFERi0Tc.JPG', 'birki-pryamokutni-cropped.webp', '', '', 'birki-pryamokutni', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(159, 'Бирки прямокутні з отворами', 123, 1, 3, '2021-11-24 04:30:05', '2025-07-30 16:10:51', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/November2021/CSuwSvpO6FrgE4quGIlI.JPG', 'birki-pryamokutni-z-otvorami-cropped.webp', '', '', 'birki-pryamokutni-z-otvorami', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(160, 'Бирки на гвинті', 123, 1, 4, '2021-11-24 04:32:25', '2025-07-30 16:10:51', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/November2021/JK0MD6j4s4pxaiwhvkrK.JPG', 'birki-na-gvinti-cropped.webp', '', '', 'birki-na-gvinti', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(161, 'Бирки круглі', 123, 1, 5, '2021-11-24 04:36:40', '2025-07-30 16:10:52', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/November2021/zrcF1KmL2IV0kzszE3AX.JPG', 'birki-krugli-cropped.webp', '', '', 'birki-krugli', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(162, 'Косметички "Серце"', 28, 1, 21, '2022-02-03 03:41:21', '2025-10-01 20:46:30', NULL, '', NULL, '', NULL, NULL, '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Серед аксесуарів жінки обов''язково є косметичка.&nbsp;<strong>Містка косметичка</strong>&nbsp;від&nbsp;<a href="../../">Лавокс</a>&nbsp;з&nbsp;<strong>натуральної шкіри</strong>&nbsp;буде надійним помічником при зберіганні найнеобхідніших косметичних засобів, які щодня потрібні кожній жінці. Компактні і лаконічні косметички виробника помістяться у&nbsp;<a href="../../zhinochi/sumki">жіночій сумці</a>&nbsp;або невеликому&nbsp;<a href="../../ryukzaki">рюкзаку</a>. А стриманий стиль аксесуара може сподобатися і чоловікам.&nbsp;<strong>Косметичка</strong>&nbsp;завдяки універсальній формі і можливості вибору кольору успішно застосовується як&nbsp;<em>пенал</em>&nbsp;для ділової людини.</p>\n<p>Форма косметички у вигляді серця - гарний подарунок на <a href="../../ru/zhenskie/sumki">день закоханих</a> , або просто нагадати про <a href="../../ru/zhenskie/sumki">кохання</a>&nbsp;</p>\n<p>Косметичка "Серце" має розмір в діаметрі 11см, а висота 3,5 см. Може бути виконана в будь-якому кольорі.</p>', '', 'categories/February2022/I6wliitbXMnQiiLvAExw.JPG', 'kosmetichki-serce-cropped.webp', '', '', 'kosmetichki-serce', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(163, 'Дровниця зі шкіри', 28, 1, 34, '2022-02-03 04:53:26', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '<p>Серед аксесуарів досить рідко зустрінеш саме цей.&nbsp; <strong>Містка дровниця </strong>&nbsp;від <a>Лавокс</a> з&nbsp;<strong>натуральної шкіри</strong> буде надійним помічником при переносці дров, навіть дуже тяжких або різної довжини. В шкіряній дровниці можливо безпечно та надійно переносити нарізанні дрова, не розсипаючи&nbsp; деревину, або кору по дорозі до <a href="../../ru/ryukzak">камина</a>.&nbsp; А стриманий стиль аксесуара напевно сподобається найвибаглівишим&nbsp; чоловікам и може бути використаним як&nbsp; <strong>подарунок</strong> для людини, яку складно чимось здивувати.&nbsp;</p>', '', 'categories/February2022/ufbFSnvOjbcBf71d090a.JPG', 'drovnicya-zi-shkiri-cropped.webp', '', '', 'drovnicya-zi-shkiri', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(164, 'Поясні сумки "Дізі-2"', 24, 1, 3, '2022-05-19 12:52:04', '2025-07-30 16:10:58', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/FGttUHTSVx8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Поясна сумка &laquo;Дізі&raquo; досить немаленького розміру. Має попереду кишеню на блискавці, позаду теж є кишеня на блискавці. Відкривається сумка на блискавку, і всередині ще 2 звичайні кишеньки. Вся підкладка в кишенях зроблена з тонкої шкіри. Найголовніша &laquo;фішка&raquo; сумки -застібка ременя на кільце -карабін. Це дуже зручно і досить красиво і оригінально. При замовленні переконливе прохання казати для чоловіка або жінки сумка-довжина ремінця відрізняється. <strong>Відміністю від класичної сумки "Дізі" є розширене дно, що робить внутрішній об"єм сумки більшим.</strong></p>', '', 'categories/May2022/2MOzaobcZvVWMQNIUe4V.JPG', 'poyasni-sumki-dizi-2-cropped.webp', '', '', 'poyasni-sumki-dizi-2', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
