(177, 'Гаманці "Вайнот"', 25, 1, 2, '2023-03-17 01:33:43', '2025-10-29 14:10:25', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/8aafXrUUwC8" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Гаманець "Вайнот" ще можна назвати&nbsp; клатчем. Має застібку на металеву "блискавку" по периметру. Всередині 4 відділення під картки, в кожне з яких входить по 2-3 картки. Також є два просторих відділення, в які увійде багато грошових купюр будь-якого формату або смартфон будь-якого розміру, а ще поміститься паспорт в обкладинці. Плюс ще два пласких відділення для паперових купюр. Посередині э ще одне відділення на блискавці (YKK), в якому можна розміщувати монетки або ще щось). Розмір 19,0х10,5х2,0 см.</p>', '', 'categories/October2025/NUbRYYUUixHBmyKWFOGh.jpg', 'gamanci-vajnot-cropped.webp', '', '', 'gamanci-vajnot', NULL, 'daily', '', '', NULL, NULL, 0, -5, NULL, NULL),
(178, 'Обкладинкі на посвідчення "Бюро економічної безпеки України", БЕБ', 29, 1, 15, '2023-03-22 04:17:52', '2026-02-04 03:50:59', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення "Бюро економічної безпеки України" ( БЕБ) - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/March2023/7d2cBswCppc3q0EIHQAH.JPG', 'obkladinki-na-posvidchennya-byuro-ekonomichnoyi-bezpeki-ukrayini-beb-cropped.webp', '', '', 'obkladinki-na-posvidchennya-byuro-ekonomichnoyi-bezpeki-ukrayini-beb', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(179, 'Обкладинкі на посвідчення універсальні', 29, 1, 2, '2023-03-28 02:53:21', '2026-02-04 03:51:05', NULL, '', NULL, '', NULL, NULL, '<p>"Обкладинка на посвідчення універсальна"&nbsp; - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/March2023/ZX2dwgjbfYhwEilmHYlK.JPG', 'obkladinki-na-posvidchennya-universal-ni-cropped.webp', '', '', 'obkladinki-na-posvidchennya-universal-ni', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(180, 'Обкладинкі на посвідчення універсальні 2', 29, 1, 3, '2023-03-29 19:40:34', '2026-02-04 03:51:05', NULL, '', NULL, '', NULL, NULL, '<p>"Обкладинка на посвідчення універсальна 2"&nbsp; - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з двома прозорими віконцями.</p>', '', 'categories/March2023/igA3xunEyVN4RAgLHI90.JPG', 'obkladinki-na-posvidchennya-universal-ni-2-cropped.webp', '', '', 'obkladinki-na-posvidchennya-universal-ni-2', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(181, 'Тиснення українською мовою', 88, 1, 2, '2023-04-02 22:48:28', '2025-07-30 16:11:23', NULL, '', NULL, '', NULL, NULL, '<p><iframe src="https://www.youtube.com/embed/kFKIP4P87UY" width="313" height="176" allowfullscreen="allowfullscreen"></iframe>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Робимо <a href="https://lavoks.com/tisnennya">тиснення</a> українською мовою, кирилецею. Мова йде про <a href="https://lavoks.com/tisnennya">тиснення</a> на виробах як&nbsp; власного виробництва, так&nbsp; і по можливості на виробах клієнта.&nbsp; Є велики та маленькі літери, приклади шрифту на фото. Ціна на сайті розрахована за одне <a href="https://lavoks.com/tisnennya">тиснення</a>, яким вважається слово до 10-12 знаків. Також для <a href="https://lavoks.com/tisnennya">тиснення</a> у нас є багато різних сиволів, наявність яких саме можна подивитися в розділі сайту "Символи для <a href="https://lavoks.com/tisnennya">тиснення</a> які є в наявності".</p>', '', 'categories/April2023/8rT9ccoFWfljM6MUOjKk.JPG', 'tisnennya-ukrayins-koyu-movoyu-cropped.webp', '', '', 'tisnennya-ukrayins-koyu-movoyu', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(182, 'Обкладинкі на посвідчення адвоката', 29, 1, 14, '2023-04-03 03:09:04', '2026-02-04 03:50:59', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення адвоката - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/April2023/IZqpGcrlvDHm9Hh2POSg.JPG', 'obkladinki-na-posvidchennya-advokata-cropped.webp', '', '', 'obkladinki-na-posvidchennya-advokata', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(183, 'Килимки для робочого столу', 28, 1, 32, '2023-04-10 20:26:46', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '<p>Килимок для робого столу з натуральної шкіри стандарно робимо в розмірі 75 см х 35 см. Виготовити можна в любому кольорі і в любому розмірі на замовлення.</p>', '', 'categories/April2023/1xfeNg5Y6hadWnFClMDg.JPG', 'kilimki-dlya-robochogo-stolu-cropped.webp', '', '', 'kilimki-dlya-robochogo-stolu', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(184, 'Обкладинкі на посвідчення універсальні 3', 29, 1, 4, '2023-04-27 19:19:15', '2026-02-04 03:51:05', NULL, '', NULL, '', NULL, NULL, '<p>"Обкладинка на посвідчення універсальна 3"&nbsp; - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з трьома прозорими віконцями.</p>', '', 'categories/April2023/fyhxHJUR08SmyEaqPZeZ.JPG', 'obkladinki-na-posvidchennya-universal-ni-3-cropped.webp', '', '', 'obkladinki-na-posvidchennya-universal-ni-3', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(185, 'Поясні  сумки "Лакі"', 24, 1, 1, '2023-05-19 03:04:18', '2025-07-30 16:11:59', NULL, '', NULL, '', NULL, NULL, '<p>Рецепт зручності на кожен день - поясна сумка "Лакі". Туди вміститься все найнеобхідніше, а руки будуть вільними. Всередині "відкрита" кишеня. Зроблена повністю з натуральної шкіри. Пояс регулюється, та зазвичай носять таку сумку як "кроссбоді".&nbsp; Розміри - довжина 24см., висота 13см., глибина 8см. Можна зробити з тканевою підкладкою (додаткова опція), можна зробити комбінування різних кольорів, можна додати кишеню&nbsp; позаду на замочку. Фантазуйте!</p>', '', 'categories/May2023/5vlNCCfyGBOIOru6vhah.JPG', 'poyasni-sumki-laki-cropped.webp', '', '', 'poyasni-sumki-laki', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(186, 'Сумки "Мона"', 23, 1, 24, '2023-05-23 03:43:22', '2025-11-14 17:50:12', NULL, '', NULL, '', NULL, NULL, '<p>Розмір сумки 22 см х 19 см. Всередині одне велике відділення та кишеня.</p>', '', 'categories/May2023/aaDCYc5H875ksCZTt767.JPG', 'sumki-mona-cropped.webp', '', '', 'sumki-mona', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(187, 'Обкладинкі на посвідчення учасника бойових дій, УБД', 29, 1, 9, '2023-05-23 03:55:38', '2026-02-04 03:50:58', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка для посвідчення учасника бойових дій (УБД). Або для будь-якого іншого документу, який має розмір 10*7 см., в складеному вигляді. Всередині два прозорих віконця. <a href="https://lavoks.com/tisnennya">Тиснення</a> попереду виробу - стандартні, та можна зробити і інше <a href="https://lavoks.com/tisnennya">тиснення</a> (українською або англійською мовою).&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', '', 'categories/May2023/zssdYKTlWBIbCzyjc2NB.JPG', 'obkladinki-na-posvidchennya-uchasnika-bojovih-dij-ubd-cropped.webp', '', '', 'obkladinki-na-posvidchennya-uchasnika-bojovih-dij-ubd', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(188, 'Бирки овальні', 123, 1, 6, '2023-05-30 04:47:24', '2025-07-30 16:12:01', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/May2023/Wr3T9hJzRpRz5y4vKrsE.JPG', 'birki-oval-ni-cropped.webp', '', '', 'birki-oval-ni', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(189, 'Бирки двосторонні', 123, 1, 7, '2023-05-30 05:08:48', '2025-07-30 16:12:02', NULL, '', NULL, '', NULL, NULL, '<p>Один з найпошириніших виробів зі шкіри це бирка. Виробники джинсів, курток, взуття, сумок, шапок, кофт, різноманітних промислових виробів і просто безлічі товарів, ідентифікують назву свого бренду саме завдяки биркам, які гордо носять логотип компанії виробника.&nbsp; Ми можемо запропонувати виробникам товарів виготовлення бирок з натуральної шкіри різних форм, розміру та складності і нанессеня на них лого методом гарячого <a href="https://lavoks.com/tisnennya">тиснення</a>. Можемо запропонувати більше 120 кольорів та видів шкіри. Для роботи з нами потрібно кліше (або файл з лого вашої фірми), бажаний розмір та форма бирки. Ми супроводжуємо виготовлення кліше якщо у вас його нема ( вартість залежить від розміру, в середньому 200 грн.), і в максимально короткі строки зробимо Вам будь-яку партію якісних бирок з натуральної шкіри.&nbsp;</p>', '', 'categories/May2023/ChBKBllNgui0IQUrdKAm.JPG', 'birki-dvostoronni-cropped.webp', '', '', 'birki-dvostoronni', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(190, 'Чохоли для гарнітури авіадіспетчера', 28, 1, 36, '2023-06-02 03:36:20', '2026-04-01 00:51:35', NULL, '', NULL, '', NULL, NULL, '<p><strong>Чохол, сумка для гарнітури авіадіспетчера</strong></p>', '', 'categories/June2023/MFC7WfFUQr7CVJpsrDdD.JPG', 'choholi-dlya-garnituri-aviadispetchera-cropped.webp', '', '', 'choholi-dlya-garnituri-aviadispetchera', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(191, 'Обкладинкі на посідчення "Київська міська державна адміністрація", КМДА', 29, 1, 17, '2023-07-12 03:02:44', '2026-02-04 03:50:54', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення "Київська міська державна адміністрація" (КМДА) - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/July2023/fYEBLrmtDn3LNZQLTj8r.JPG', 'obkladinki-na-posidchennya-kiyivs-ka-mis-ka-derzhavna-administraciya-kmda-cropped.webp', '', '', 'obkladinki-na-posidchennya-kiyivs-ka-mis-ka-derzhavna-administraciya-kmda', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(192, 'Обкладинкі на посвідчення "Міністерство внутрішніх справ України", МВС ', 29, 1, 16, '2023-07-28 13:33:19', '2026-02-04 03:50:59', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення "Міністерство внутрішніх справ України" (МВС) - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/July2023/IP3gE2ttVLrBtyD27PCy.JPG', 'obkladinki-na-posvidchennya-ministerstvo-vnutrishnih-sprav-ukrayini-mvs-cropped.webp', '', '', 'obkladinki-na-posvidchennya-ministerstvo-vnutrishnih-sprav-ukrayini-mvs', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(193, 'Сумки-шоппери "Барселона"', 23, 1, 8, '2023-09-20 13:32:21', '2025-11-14 17:50:28', NULL, 'Сумка-тоут «Барселона» 29×36×12 см | 150+ видів шкіри | Ручна робота', NULL, 'Сумка-тоут «Барселона» (29×36×12 см) без підкладки — мінімалізм і натуральна шкіра. 150+ кольорів і текстур: саф’яно, металік, крейзі хорс. Ручна робота, магнітна застібка, кишеня на блискавці. Доставка по Україні 1–3 дні.', NULL, NULL, '<h1>Сумка-тоут «Барселона» (29 × 36 × 12 см): Мінімалізм, шкіра, свобода</h1><p><strong>«Барселона»</strong> — це елегантність без зайвого. Натхненна Гауді та середземноморським ритмом, вона втілює чистий мінімалізм у натуральній шкірі. Розміри <strong>29 см (ширина) × 36 см (висота) × 12 см (глибина)</strong> — ідеальний баланс для щоденного використання. Доступна <strong>у понад 150 видах шкіри</strong>: гладка, металізована, саф’яно, крейзі хорс, pull-up. Кожна — унікальна за текстурою та характером.</p><hr><h2>Дизайн: чистота ліній</h2><p>Прямокутна форма, м’які краї, дві широкі ручки (~55 см). Без каркасу — набуває форми вмісту. Ручна робота: акуратні шви, мінімальні припуски. Ніякої фурнітури — лише шкіра говорить.</p><p><em>SEO:</em> сумка-тоут Барселона, мінімалістична шкіряна сумка, сумка без підкладки.</p><hr><h2>Шкіра: 150+ варіантів</h2><ul><li><strong>Гладка теляча</strong> — діловий стиль</li><li><strong>Металізована</strong> — вечірній блиск</li><li><strong>Крейзі хорс</strong> — вінтаж з часом</li><li><strong>Саф’яно</strong> — класика з текстурою</li><li><strong>Лакована</strong> — захист від дощу</li></ul><p>Товщина 1,2–1,6 мм, натуральна виворотка (без підкладки). Легка, дихаюча, зносостійка.</p><p><br></p><hr><h2>Функціональність</h2><ul><li><strong>29 см ширина</strong> — А4, ноутбук 13"</li><li><strong>36 см висота</strong> — пляшка 0,5 л вертикально</li><li><strong>12 см глибина</strong> — гаманець, косметичка, телефон</li></ul><p><strong>Всередині:</strong></p><ul><li>Одне відкрите відділення</li><li>Кишеня на блискавці (20 × 15 см)</li><li>Магнітна кнопка зверху</li></ul><p>Ручки — подвійна шкіра, шви армовані. Витримує <strong>до 8 кг</strong>.</p><p><br></p><hr><h2>Універсальність</h2><table> <thead> <tr> <th><div>Ситуація</div></th> <th><div>Образ</div></th> <th><div>Шкіра</div></th> </tr> </thead> <tbody> <tr> <td><div>Офіс</div></td> <td><div>Сорочка + джинси</div></td> <td><div>Чорний саф’яно</div></td> </tr> <tr> <td><div>Вечір</div></td> <td><div>Сукня</div></td> <td><div>Золото</div></td> </tr> <tr> <td><div>Подорож</div></td> <td><div>Льон</div></td> <td><div>Крейзі хорс</div></td> </tr> <tr> <td><div>Шопінг</div></td> <td><div>Тренч</div></td> <td><div>Бежевий</div></td> </tr> </tbody></table><p>Пасує до всього — від піджака до худі.</p><p><br></p><hr><h2>Догляд</h2><ol><li>Спрей для захисту перед виходом</li><li>Протирати вологою мікрофіброю</li><li>Зберігати в тканинному мішку, набитою папером</li><li>Уникати сонця (особливо металіку)</li></ol><p><br></p><hr><h2>Чому варто?</h2><ul><li><strong>Ручна робота</strong> — 4–6 годин на виріб</li><li><strong>150+ шкір</strong> — ексклюзив</li><li><strong>7–10 років служби</strong></li><li><strong>Без підкладки</strong> — легше, натуральніше</li></ul><hr><h2>«Барселона» — ваша історія</h2><p>З часом з’являються потертості, складки, унікальний відтінок. Це не просто сумка — це ваш супутник.</p><hr><h3>Замовити зараз</h3><ul><li><strong>29 × 36 × 12 см</strong></li><li><strong>150+ шкір</strong></li><li><strong>Доставка 1–3 дні</strong></li><li><strong>Оплата при отриманні</strong></li><li><strong>Повернення — 14 днів</strong></li></ul><p>Оберіть свою. <strong>«Барселона»</strong> готова.</p><hr><p><br></p>', '', 'categories/November2025/PgJ5cutLS5XRJiOIsWsx.jpg', 'sumki-shopperi-barselona-cropped.webp', 'Сумка-тоут «Барселона» — мінімалізм у 150+ видах натуральної шкіри', '<p>Шкіряна сумка-тоут <strong>«Барселона»</strong> — втілення мінімалізму та свободи. Розміри <strong>29×36×12 см</strong>, без підкладки, ручна робота. Доступна у <strong>понад 150 видах шкіри</strong>: саф’яно, крейзі хорс, металік, гладка теляча. Магнітна застібка, внутрішня кишеня на блискавці. Витримує до 8 кг. Доставка по Україні — 1–3 дні. Купити сумку «Барселона» з натуральної шкіри — обрати стиль, якість і унікальність.</p>', 'sumki-shopperi-barselona', NULL, 'daily', 'Сумка «Барселона» з натуральної шкіри | 29×36×12 | Без підкладки', 'Мінімалістична сумка-тоут «Барселона» з натуральної шкіри без підкладки. Розміри: 29×36×12 см. 150+ варіантів: гладка, саф’яно, металік. Ручна робота, магніт, кишеня. Ідеальна для офісу, подорожей, шопінгу.', NULL, NULL, 0, NULL, NULL, NULL),
(195, 'Обкладинкі на посвідчення "Державна прикордонна служба України", ДПСУ', 29, 1, 23, '2023-12-13 18:07:42', '2026-02-04 03:50:54', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення "Державна прикордонна служба України", ДПСУ .&nbsp;</p>', '', 'categories/March2025/rKRDjlMCx8JjK5UcUVvZ.JPG', 'obkladinki-na-posvidchennya-derzhavna-prikordonna-sluzhba-ukrayini-dpsu-cropped.webp', '', '', 'obkladinki-na-posvidchennya-derzhavna-prikordonna-sluzhba-ukrayini-dpsu', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(196, 'Сумки-шоппери "Верона"', 23, 1, 10, '2024-01-26 01:38:11', '2025-11-14 17:50:28', NULL, '', NULL, '', NULL, NULL, '<div class="xdj266r x11i5rnm xat24cr x1mh8g0r x1vvkbs x126k92a">\n<div dir="auto">Сумка з натуральної шкіри "Верона" для тих, хто любить сумки торби та сумки шоппери, або взагалі великі сумки. Регульовані ремінці, що дають змогу носити сумку в найзручніший для себе спосіб, як на плечі, так і в руці. Вражаюча місткість, що дозволяє взяти з собою все необхідне і ще трошки, Розмір гарний, 33*32*10см. Зовні 2 кишені попереду та позаду кишеня на замочку блискавка. Всередині 2 відділи, які розділяє велика кишеня на замочку. Також всередині позаду є кишеня на замочку і ще 2 кишені звичайні попереду. В нашій колекції ця сумка маї більше всього кишень.</div>\n</div>', '', 'categories/January2024/K7rEH7ynq1VhvRrJdP8M.JPG', 'sumki-shopperi-verona-cropped.webp', '', '', 'sumki-shopperi-verona', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(197, 'Сумки-шоппери "Лаура"', 23, 1, 9, '2024-02-27 01:54:19', '2025-11-14 17:50:28', NULL, '', NULL, '', NULL, NULL, '<p>Сумка -&nbsp; повсякденний аксесуар практично&nbsp; кожної людини. Від свого виду і призначення сумки бувають різними і відрізняються розміром, формою, стилем, основним матеріалом, декором, функціоналом. Матеріал сумки - найважливіша характеристика, що впливає на якість і зносостійкість виробу. Шкіряні моделі - безумовні фаворити серед українців. В нас ви можете обрати шкіру, колір, колір нитки та колір фурнітури яка буде тільки у вас. Для найсміливіших ми можемо пошити різнокольору сумку. Фантазуйте! А ми пошиємо та відправимо вам все це за 1-3 дні.&nbsp;</p>\n<p>Сумка з натуральної шкіри "Лаура" це сумка база. Сумка на кожен день. Проста класична модель. Розмір: висота 30см., довжина 32 см., глибина 10 см.&nbsp;<br />Має велику кількість кишень. Позаду зовні є кишеня на замочку. Всередині одна кишеня на замочку і одна звичайна. А ще там є 2 напівкишені, куди також можна покласти якісь дрібнички. Також є карабін для ключів на шкіряному шнурі.&nbsp;<br /><br /></p>', '', 'categories/February2024/sNePtSTeelsOv4u5BFt4.JPG', 'sumki-shopperi-laura-cropped.webp', '', '', 'sumki-shopperi-laura', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(198, 'Рюкзаки "Річі"', 26, 1, 6, '2024-03-21 01:29:10', '2025-11-25 18:59:13', NULL, 'Шкіряний рюкзак Річі | Великий для ноутбука 15.6" | Купити в Києві', NULL, 'Купити великий шкіряний рюкзак Річі з натуральної шкіри (crazy horse, кайзер, крокодил). Вміщує ноутбук 15.6", 5+ кишень, кастомізація кольору та фурнітури. Універсальний унісекс для чоловіків і жінок. Доставка по Україні!', NULL, NULL, '<h1>Шкіряний рюкзак "Річі": універсальний іміджевий аксесуар для сучасного життя</h1><p>У сучасному світі рюкзаки давно вийшли за межі шкільних і студентських дворищ, де вони слугували простим носіями підручників і зошитів. Сьогодні <strong>шкіряний рюкзак</strong> – це не просто практичний елемент гардеробу, а справжній символ стилю, статусу та функціональності. Якщо раніше велетенські моделі з безліччю кишень асоціювалися виключно з мандрівниками та туристами, то тепер <strong>великий шкіряний рюкзак</strong> став невід''ємною частиною повсякденного іміджу для чоловіків і жінок будь-якого віку. Він ідеально вписується в урбаністичний ритм: від ранкових зустрічей у кав''ярні до вечірніх прогулянок містом чи діловими поїздками. Мода диктує свої правила – форми стали унісекс, а акценти на кольорах дозволяють легко адаптувати аксесуар під чоловічий чи жіночий гардероб. Темні тони (чорний, глибокий коричневий, насичений синій) підкреслюють стриману елегантність для чоловіків, тоді як яскраві чи пастельні відтінки додають жіночому образу грайливості та свіжості. <strong>Рюкзак з натуральної шкіри "Річі"</strong> – це втілення цієї еволюції: класичний дизайн, виняткова якість і безмежні можливості кастомізації, які роблять його унікальним для кожного власника.</p><h2>Дизайн і ергономіка: комфорт у кожній деталі</h2><p><strong>Шкіряний рюкзак "Річі"</strong> привертає увагу своєю лаконічною, але виразною формою – прямокутний силует з чіткими лініями, що нагадує мінімалістичний багаж преміум-класу. Розміри 44 × 31 × 12 см роблять його справжнім "велетнем" серед міських рюкзаків: достатньо просторим, щоб вмістити все необхідне для активного дня, але не громіздким, аби не сковувати рухи. Верхня ручка з потовщеного шкіряного ременя дозволяє легко переносити рюкзак у руці, а регульовані лямки з м''яким наповнювачем розподіляють вагу рівномірно по спині, запобігаючи дискомфорту навіть під час тривалих прогулянок.</p><p>Фурнітура –якісні&nbsp; блискавки в антік або нікель кольорі забезпечують надійне закриття.&nbsp; На фото ви бачите класичний коричневий варіант з crazy horse – шкірою, яка з часом набуває унікальної патини, ніби розповідаючи історію свого власника. Але "Річі" – це не моноліт: ми шиємо його з різних типів натуральної шкіри, щоб підкреслити індивідуальність. Для любителів класики – гладка&nbsp; шкіра кайзер з легким блиском, ідеальна для бізнес-луків.&nbsp; А для тих, хто прагне розкоші, – тиснення під крокодила чи каймана: текстура, що імітує екзотичну рептилію, додає рюкзаку статусу, ніби це аксесуар з колекції haute couture. Кольорова гама безмежна: від глибокого шоколадного для <strong>чоловічого шкіряного рюкзака</strong> до м''ятного чи бордового для жіночого – все на ваш смак. Бажання різнокольоровості? Ми комбінуємо панелі: наприклад, основа в чорному з акцентами в теракотовому для динамічного міського стилю.</p><h2>Функціональність: все під рукою, без компромісів</h2><p><strong>Великий рюкзак для ноутбука "Річі"</strong> – це не просто красива оболонка, а продумана система зберігання, яка перетворює хаос речей на організований простір. Головне відділення на блискавці вміщує ноутбук до 15,6 дюймів у спеціальній кишені з. Додаткові внутрішні кишені, одна на блискавці для дрібниць (ключі, навушники), інша – для швидкого доступу до документів чи зарядки. Зовні – зовнішня кишеня спереду з двома блискавками, і потайна задня кишеня на замочку для паспорта чи проїзного. Загалом – понад 5 відділень, що робить "Річі" ідеальним <strong>рюкзаком для подорожей</strong>, <strong>офісним рюкзаком</strong> чи щоденним супутником фрілансера.</p><p>Об''єм близько 16-18 літрів дозволяє пакувати не тільки гаджети, але й одяг на вихідні, книги чи спортивну форму. А якщо ви мандрівник, то регульовані лямки&nbsp; перетворять його на надійного компаньйона для хайкінгу. Вага порожнього рюкзака – лише 1,3 кг, завдяки легкій, але міцній конструкції. Усе шиється вручну нашими майстрами зі шкір українського та італійського виробництва, з надійними швами для довговічності – цей рюкзак прослужить роки, набуваючи шарму з кожним днем.</p><h2>Стиль і універсальність: від casual до business</h2><p><strong>Чоловічий рюкзак з шкіри "Річі"</strong> у темних тонах – must-have для урбаніста: поєднуйте з джинсами, челсі та шкіряною курткою для street-style, або з костюмом для smart-casual. Жіночий варіант у пастельних відтінках додає легкості образу: з сукнею-міді чи oversize-светром – і ви готова до шопінгу чи зустрічі з подругами. Унісекс-форма робить його універсальним: висота дозволяє носити з будь-яким зростом, а мінімалізм не перевантажує силует. Додайте персоналізацію – <a href="https://lavoks.com/tisnennya">тиснення</a> ініціалів чи монограми на передній панелі – і рюкзак стане ексклюзивним.</p><p>Чому "Річі" – вибір свідомих? Бо це етична мода: натуральні матеріали, ручна праця, що підтримує локальних ремісників. Це оптимізований вибір для тих, хто хоче&nbsp;<strong>купити шкіряний рюкзак у Києві</strong>, або <strong>замовити рюкзак з доставкою по Україні чи за кордон.</strong>&nbsp;</p><p>Готові до свого "Річі"? Оберіть тип шкіри (crazy horse, kaiser, alcor, крокодил/кайман), колір, фурнітуру – і ми втілимо вашу ідею за 2-5 днів. Замовляйте зараз і відчуйте, як стильний рюкзак змінює повсякденність!</p>', '', 'categories/November2025/KO8Fqfm7sLBcsjvkCZ2m.jpg', 'ryukzaki-richi-cropped.webp', 'Купити шкіряний рюкзак Річі: великий унісекс для ноутбука з кастомізацією', 'шкіряний рюкзак, великий рюкзак, рюкзак для ноутбука, чоловічий рюкзак, жіночий рюкзак, кастомний рюкзак, натуральна шкіра, crazy horse рюкзак, кайзер шкіра, рюкзак крокодил, рюкзак кайман, унісекс рюкзак, рюкзак Київ, замовити рюкзак Україна', 'ryukzaki-richi', NULL, 'daily', 'Рюкзак Річі: Шкіряний велетень 44x31x12 см для ноутбука | Кастом на замовлення', 'Шкіряний рюкзак Річі – стильний і місткий (16-18 л), з кишенями для гаджетів, документів і подорожей. Оберіть шкіру (алькор, кайман), колір, тиснення. Ручна робота, гарантія 1 рік. Ідеально для офісного та міського стилю.', NULL, NULL, 0, NULL, NULL, NULL),
(199, 'Обкладинкі на посвідчення офіцера', 29, 1, 8, '2024-03-28 20:56:50', '2026-02-04 03:50:58', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення офіцера, зовнішній розмір 11.5 х 9,0 см. в складеному стані. Може буде виконана в любому кольорі. Є можливість зробити індивидуальне <a href="https://lavoks.com/tisnennya">тиснення</a> &ndash; ім`я, або ініціали, або пам`ятну дату, та різні символи із тих, що є у нас на момент замовлення та представлені на нашому сайті в розділі "<a href="https://lavoks.com/tisnennya">тиснення</a>".</p>', '', 'categories/March2024/EdKo1QK3azPkiInBeIWc.JPG', 'obkladinki-na-posvidchennya-oficera-cropped.webp', '', '', 'obkladinki-na-posvidchennya-oficera', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(200, 'Обкладинкі на посвідчення особи з інвалідністю внаслідок війни', 29, 1, 10, '2024-03-28 21:05:31', '2026-05-21 18:58:38', NULL, 'Обкладинки на посвідчення особи з інвалідністю внаслідок війни з натуральної шкіри — Lavoks', NULL, 'Купити шкіряні обкладинки на посвідчення особи з інвалідністю внаслідок війни ручної роботи. Натуральна шкіра Crazy Horse, Kaiser, Alkor. Індивідуальне тиснення, великий вибір кольорів. Доставка по Україні.', NULL, NULL, '<p><br></p><blockquote><h2>Шкіряні обкладинки на посвідчення особи з інвалідністю внаслідок війни — ручна робота та надійний захист</h2><p>Посвідчення особи з інвалідністю внаслідок війни — це документ, який вимагає дбайливого зберігання та щоденного захисту від зношування. Майстерня Lavoks пропонує якісні шкіряні обкладинки на посвідчення особи з інвалідністю внаслідок війни, створені вручну з найкращих матеріалів. У нашому каталозі ви знайдете різноманітні варіанти виконання, серед яких особливою популярністю користується обкладинка книжка на посвідчення, що забезпечує швидкий доступ до документа та надійну фіксацію. Ми враховуємо всі вимоги до ергономіки, тому кожна обкладинка для посвідчення інваліда війни ідеально підходить під стандартні розміри бланка, не додаючи зайвого об''єму в кишені чи сумці.</p><p>Для виготовлення аксесуарів ми використовуємо виключно високоякісну натуральну шкіру кількох типів. Ви можете обрати вінтажну шкіру Crazy Horse (крейзі хорс) з її неповторним ефектом старіння, класичний гладкий Kaiser (кайзер) із легким глянцем або міцний та зносостійкий Alkor (алькор). В асортименті завжди є в наявності всі базові та глибокі відтінки: строгий чорний, шляхетний темно-коричневий, теплий коньячний, класичний темно-синій, а також яскравий червоний, зелений, глибокий марсала, мілітарі хакі та універсальний сірий колір.</p><p>Шукаєте унікальний подарунок або бажаєте персоналізувати власний аксесуар? Ми пропонуємо унікальну послугу — іменна обкладинка на посвідчення з тисненням. Наша майстерня виконує індивідуальне гаряче тиснення на шкірі. Для замовлення доступні українські та латинські літери, цифри, різноманітні графічні символи та обкладинка з національною символікою, зокрема з гербом України. Наш асортимент кліше для тиснення постійно розширюється, що дозволяє втілити будь-який задум. Обирайте надійність, автентичний стиль та купуйте обкладинки на посвідчення особи з інвалідністю внаслідок війни з натуральної шкіри від українського виробника Lavoks із доставкою по Києву та всій Україні.</p></blockquote><p>​</p>', '', 'categories/May2026/lNCOREInngllgJJ9dOCv.JPG', 'obkladinki-na-posvidchennya-osobi-z-invalidnistyu-vnaslidok-vijni-cropped.webp', 'Обкладинки на посвідчення особи з інвалідністю внаслідок війни', 'Шкіряні обкладинки на посвідчення особи з інвалідністю внаслідок війни — ручна робота та надійний захист\n\nПосвідчення особи з інвалідністю внаслідок війни — це документ, який вимагає дбайливого зберігання та щоденного захисту від зношування. Майстерня Lavoks пропонує якісні шкіряні обкладинки на посвідчення особи з інвалідністю внаслідок війни, створені вручну з найкращих матеріалів. У нашому каталозі ви знайдете різноманітні варіанти виконання, серед яких особливою популярністю користується обкладинка книжка на посвідчення, що забезпечує швидкий доступ до документа та надійну фіксацію. Ми враховуємо всі вимоги до ергономіки, тому кожна обкладинка для посвідчення інваліда війни ідеально підходить під стандартні розміри бланка, не додаючи зайвого об''єму в кишені чи сумці.\n\nДля виготовлення аксесуарів ми використовуємо виключно високоякісну натуральну шкіру кількох типів. Ви можете обрати вінтажну шкіру Crazy Horse (крейзі хорс) з її неповторним ефектом старіння, класичний гладкий Kaiser (кайзер) із легким глянцем або міцний та зносостійкий Alkor (алькор). В асортименті завжди є в наявності всі базові та глибокі відтінки: строгий чорний, шляхетний темно-коричневий, теплий коньячний, класичний темно-синій, а також яскравий червоний, зелений, глибокий марсала, мілітарі хакі та універсальний сірий колір.\n\nШукаєте унікальний подарунок або бажаєте персоналізувати власний аксесуар? Ми пропонуємо унікальну послугу — іменна обкладинка на посвідчення з тисненням. Наша майстерня виконує індивідуальне гаряче тиснення на шкірі. Для замовлення доступні українські та латинські літери, цифри, різноманітні графічні символи та обкладинка з національною символікою, зокрема з гербом України. Наш асортимент кліше для тиснення постійно розширюється, що дозволяє втілити будь-який задум. Обирайте надійність, автентичний стиль та купуйте обкладинки на посвідчення особи з інвалідністю внаслідок війни з натуральної шкіри від українського виробника Lavoks із доставкою по Києву та всій Україні.', 'obkladinki-na-posvidchennya-osobi-z-invalidnistyu-vnaslidok-vijni', NULL, 'daily', 'Обкладинка на посвідчення особи з інвалідністю внаслідок війни з шкіри — купити в Lavoks', 'Якісна шкіряна обкладинка для посвідчення особи з інвалідністю внаслідок війни. Натуральна шкіра, ручна робота, можливість нанесення індивідуального тиснення та національної символіки. Замовляйте на Lavoks.', NULL, NULL, 0, NULL, NULL, NULL),
(201, 'Браслети зі шкіри', 28, 1, 14, '2024-04-09 18:31:37', '2025-10-01 20:46:29', NULL, '', NULL, '', NULL, NULL, '<p>Розміри браслету з натуральної шкіри - ширина 17 мм, загальна довжина - 240 мм.&nbsp; Для регулювання довжини зроблено 4 отвори. Відстань від кобурної кнопки до отворів регулювання довжини 173 мм, 187 мм, 199 мм, 212 мм., тобто ці показники і є довжиною обхвата зап"ястя. Браслети зі шкіри можуть бути виконані в різних кольорах, переважно з ремінної шкіри. <a href="https://lavoks.com/tisnennya">Тиснення</a> на браслеті можуть бути як наші стандартні, представлені тут, так і індивідуальні, латинськими або українськими літерами та символами, які можна подивитися на цьому сайті в розділі&nbsp; "<a href="https://lavoks.com/tisnennya">тиснення</a>" - "символи для <a href="https://lavoks.com/tisnennya">тиснення</a> які є в наявності". Також в розділі <a href="https://lavoks.com/tisnennya">тиснення</a> можна подивитися шрифти латинський та український.</p>', '', 'categories/April2024/bmWqQWFbmaoTZ4MS9ls3.JPG', 'brasleti-zi-shkiri-cropped.webp', '', '', 'brasleti-zi-shkiri', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(202, 'Пояс-шнурок з натуральної шкіри', 40, 1, 13, '2024-04-09 20:16:27', '2025-07-30 16:12:20', NULL, '', NULL, '', NULL, NULL, '<p>Ремінь-шнурок виговляється з цільної високоякісної шкіри та має довжину до 240 мм</p>', '', 'categories/April2024/iXLjFekTvsvNJvFTmlZj.JPG', 'poyas-shnurok-z-natural-noyi-shkiri-cropped.webp', '', '', 'poyas-shnurok-z-natural-noyi-shkiri', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(203, 'Косметички "Прима"', 28, 1, 25, '2024-04-17 01:49:24', '2025-07-30 16:12:21', NULL, '', NULL, '', NULL, NULL, '<h1>ШКІРЯНІ КОСМЕТИЧКИ РУЧНОЇ РОБОТИ LAVOKS</h1>\n<p>Серед аксесуарів жінок та чоловіків обов''язково є косметичка. <strong>Містка косметичка</strong>&nbsp;від&nbsp;<a href="../../">Лавокс</a>&nbsp;з&nbsp;<strong>натуральної шкіри</strong>&nbsp;буде надійним помічником при зберіганні найнеобхідніших косметичних засобів, які щодня потрібні кожній жінці. Компактні і лаконічні косметички виробника помістяться у&nbsp;<a href="../../zhinochi/sumki">жіночій сумці</a> та і у <a title="чоловічі сумки" href="../../cholovicha/sumka">чоловічій сумці</a> або невеликому <a href="../../ryukzaki">рюкзаку</a>. А стриманий стиль аксесуара може сподобатися і чоловікам.&nbsp;<strong>Косметичка</strong>&nbsp;завдяки універсальній формі і можливості вибору кольору успішно застосовується як&nbsp;<em>пенал</em>&nbsp;для ділової людини.</p>\n<p>Косметичка "Пріма" Розмір зверху 22 см., знизу 14 см., висота 14 см., глибина 7 см. Може бути виконана в будь-яких кольорах. Всередині тканева підкладка.</p>', '', 'categories/April2024/wUjHULyvTP8nbkDTFsi3.JPG', 'kosmetichki-prima-cropped.webp', '', '', 'kosmetichki-prima', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(204, 'Сумки "Паті"', 23, 0, 41, '2024-05-08 03:48:18', '2025-07-30 16:12:21', NULL, '', NULL, '', NULL, NULL, '<p>Сумка -&nbsp; повсякденний аксесуар практично кожної людини. Від свого виду і призначення сумки бувають різними і відрізняються розміром, формою, стилем, основним матеріалом, декором, функціоналом. Сумка- багет вже декілька років тримає позиції і має велику кількість прихильниць. Це невелика компактна сумка, що нагадує круасан, це модний аксесуар з закругленими кутами , з короткою ручкою чи ремінцем, <span class="Y2IQFc" lang="uk">який було зручно носити на плечі.&nbsp;</span>Класична модель оснащена коротким ремінцем, який можна носити на плечі або в руці, але дизайнери постійно вносять різноманітність. Популярністю користуються шкіряні багетні сумки з товстим або вузьким ланцюжком-ремінцем, а також стьобані моделі з оригінальною пряжкою.&nbsp;</p>\n<p>Ми пропонуємо варіант сумки з замши. Сумка "Паті" має розмір 30*16 см. Всередині тканева підкладка. Всередині є кишеня на замочку. Гарною прикрасою є китиця з такої самої шкіри як і вся сумка. Кольорів багато, для будь -якого одягу чи сезону року.&nbsp;</p>', '', 'categories/May2024/75jXy1dG53bACYbfnhNb.JPG', 'sumki-pati-cropped.webp', '', '', 'sumki-pati', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(205, 'Обкладинкі на посвідчення "Комітет по боротьбі з корупцією", КБК', 29, 1, 24, '2024-06-11 01:27:13', '2026-02-04 03:50:54', NULL, '', NULL, '', NULL, NULL, '<p>Обкладинка на посвідчення "Комітет по боротьбі з корупцією" ( КБК ) - це обкладинка id формату (під стандартну пластикову картку) горизонтальної орієнтації з прозорим віконцем.&nbsp;</p>', '', 'categories/June2024/jqOSchuLiuR0SqTxdHQQ.JPG', 'obkladinki-na-posvidchennya-komitet-po-borot-bi-z-korupciyeyu-kbk-cropped.webp', '', '', 'obkladinki-na-posvidchennya-komitet-po-borot-bi-z-korupciyeyu-kbk', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL),
(206, 'test', NULL, 0, 13, '2024-10-12 15:16:50', '2025-08-20 18:35:27', NULL, '', NULL, '', NULL, NULL, '<h2>Сумка-тоут "Пакет зі шкіри, розмір L": Досконалість мінімалізму та бездоганний стиль</h2><p>У світі мінливих трендів справжня класика завжди залишається в моді. Сумка-тоут "Пакет зі шкіри, розмір L" — це втілення мінімалізму, функціональності та елегантності, створене для тих, хто цінує лаконічний дизайн і високу якість. Вона стане вашим ідеальним супутником у повсякденному житті, на роботі чи прогулянках, підкреслюючи витончений смак і впевненість.</p><p><strong>Елегантність у простоті</strong></p><p>Натхненна формою паперового пакета, ця сумка виконана з натуральної шкіри, що додає їй розкішного вигляду. Прямокутна форма, чисті лінії та відсутність зайвих деталей роблять її універсальним аксесуаром — від ділового стилю до кежуал. Справжня краса цієї моделі криється в її лаконічності.</p><p><strong>Якість, що триває</strong></p><p>Виготовлена з високоякісної натуральної шкіри, сумка відзначається міцністю та довговічністю. Кожна деталь створюється вручну досвідченими майстрами, а міцні ручки та продуманий внутрішній простір забезпечують зручність і надійність на роки.</p><p><strong>Функціональність і місткість</strong></p><p>З розмірами 28х35х14 см, сумка-тоут "Пакет зі шкіри, розмір L" ідеально підходить для повсякденного використання. Вона легко вмістить гаманець, телефон, документи та інші необхідні речі, поєднуючи компактність із практичною місткістю.</p><p><strong>Універсальність і індивідуальність</strong></p><p>Доступна в різних кольорах і видах шкіри, ця модель дозволяє експериментувати зі стилем. Ви можете обрати класичний чорний або сміливіші відтінки, адаптуючи сумку до свого настрою чи гардеробу.</p><p><strong>Сумка, що відображає вашу історію</strong></p><p>Цей аксесуар — не просто річ, а відображення вашої особистості. З кожним використанням вона набуває унікального характеру, стаючи частиною ваших важливих моментів.</p><p><strong>Догляд за сумкою</strong></p><p>Щоб сумка служила довго, дотримуйтесь простих порад: використовуйте засоби для захисту шкіри, очищайте м’якою ганчіркою та зберігайте в сухому місці подалі від сонця.</p><p><strong>Інвестиція в стиль</strong></p><p>Сумка-тоут "Пакет зі шкіри, розмір L" — це вибір на користь якості та довговічності. Додайте її до свого образу вже сьогодні!</p>', '', NULL, NULL, '', '', 'test', NULL, 'daily', '', '', NULL, NULL, 0, NULL, NULL, NULL);
